// Fitted action values for holding with / against the latest impulse.
// Trained with 18 Bellman updates on independently generated paths and a
// nine-basis-point one-way execution-cost model. Runtime inputs are causal.
struct Node { feature: u8, threshold: f64, left: u16, right: u16, value: f64 }
fn predict(x: &[f32;27], roots: &[usize], nodes: &[Node], bias: f64) -> f64 { let mut y=bias; for &root in roots { let mut i=root; loop {let n=&nodes[i]; if n.left==0 { y+=n.value; break; } i=root+if (x[n.feature as usize] as f64)<=n.threshold {n.left as usize} else {n.right as usize}; }} y }
